// ===== 1. OBTENER DATA DEL WEBHOOK =====
const webhookData = $('Webhook Evolution API').first().json;

// Soporte para distintas estructuras posibles
const data = webhookData?.body?.data || webhookData?.data || webhookData;

// ===== 2. DATOS BÁSICOS =====
const messageType = data?.messageType || 'unknown';

let userMessage = '';
let phoneNumber = data?.key?.remoteJid?.replace('@s.whatsapp.net', '') 
  || data?.sender 
  || data?.from 
  || `user_${Date.now()}`;
let pushName = data?.pushName || 'Cliente';

// ===== 3. PROCESAR MENSAJE =====
if (messageType === 'conversation') {
  userMessage = data?.message?.conversation || '';
}
else if (messageType === 'extendedTextMessage') {
  userMessage = data?.message?.extendedTextMessage?.text || '';
}
else if (messageType === 'audioMessage') {
  try {
    const transcription = $('Transcribir con Whisper').first();
    userMessage = transcription?.json?.text || '[Audio no transcrito]';
  } catch (e) {
    userMessage = '[Error al transcribir audio]';
  }
}
else {
  userMessage = '[Tipo de mensaje no soportado]';
}

// ===== 4. SUPABASE CONFIG =====
const SUPABASE_URL = 'https://almfsjxrajxmyfygrtdj.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImFsbWZzanhyYWp4bXlmeWdydGRqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NjA4MjgxNCwiZXhwIjoyMDkxNjU4ODE0fQ.Xl2UET3CuRVpXDamKW1_wMJJYcxQWihpzuL0TaCLn_E'; // ⚠️ IMPORTANTE: usar service_role key

const headers = {
  apikey: SUPABASE_KEY,
  Authorization: `Bearer ${SUPABASE_KEY}`,
  'Content-Type': 'application/json'
};

// ===== 5. TRAER BOWLS DISPONIBLES =====
let bowls = [];

try {
  const response = await fetch(
    `${SUPABASE_URL}/rest/v1/products?available=eq.true`,
    {
      method: 'GET',
      headers
    }
  );

  const bowlsResult = await response.json();

  if (Array.isArray(bowlsResult)) {
    bowls = bowlsResult;
  }

} catch (error) {
  console.log('Error trayendo bowls:', error);
}

// ===== 6. BOWLS DISPONIBLES HOY =====
let bowlsDisponibles = 0;

try {
  const configResponse = await fetch(
    `${SUPABASE_URL}/rest/v1/config_diaria?fecha=eq.${new Date().toISOString().split('T')[0]}`,
    {
      method: 'GET',
      headers
    }
  );

  const configResult = await configResponse.json();

  if (Array.isArray(configResult) && configResult.length > 0) {
    const config = configResult[0];
    bowlsDisponibles = config.bowls_total - config.bowls_vendidos;
  }

} catch (error) {
  console.log('Error trayendo config:', error);
}

// ===== 7. OUTPUT FINAL =====
return [
  {
    json: {
      chatInput: userMessage,
      sessionId: phoneNumber,
      sessionKey: phoneNumber,
      phoneNumber: phoneNumber,
      pushName: pushName,
      instanceName: webhookData?.body?.instance || webhookData?.instance || '',
      messageType: messageType,
      timestamp: new Date().toISOString(),
      bowls_available: bowls.map(b => `${b.name} - $${b.price}`).join(', '),
      bowls_count: bowlsDisponibles,
      bowls: bowls
    }
  }
];

const action = query.action;
const customer_name = query.customer_name;
const customer_phone = query.customer_phone;
const customer_address = query.customer_address;
const bowl_id = query.bowl_id;
const bowl_nombre = query.bowl_nombre;
const total = query.total;
const notes = query.notes;
const order_id = query.order_id;

const SUPABASE_URL = 'https://almfsjxrajxmyfygrtdj.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImFsbWZzanhyYWp4bXlmeWdydGRqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NjA4MjgxNCwiZXhwIjoyMDkxNjU4ODE0fQ.Xl2UET3CuRVpXDamKW1_wMJJYcxQWihpzuL0TaCLn_E';

const headers = {
  'apikey': SUPABASE_KEY,
  'Authorization': `Bearer ${SUPABASE_KEY}`,
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

try {
  if (action === 'save') {
    // 1. Crear pedido
    const saveResult = await this.helpers.httpRequest({
      method: 'POST',
      url: `${SUPABASE_URL}/rest/v1/orders`,
      headers,
      body: JSON.stringify({
        customer_name: customer_name,
        customer_phone: customer_phone,
        customer_address: customer_address || null,
        status: 'pending',
        total: total,
        notes: notes
      })
    });

    const order = Array.isArray(saveResult) ? saveResult[0] : saveResult;
    const newOrderId = order.id;

    // 2. Crear order_items
    if (bowl_id && bowl_nombre) {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${SUPABASE_URL}/rest/v1/order_items`,
        headers,
        body: JSON.stringify({
          order_id: newOrderId,
          product_id: bowl_id,
          quantity: 1,
          unit_price: total
        })
      });
    }

    // 3. Actualizar a confirmed
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SUPABASE_URL}/rest/v1/orders?id=eq.${newOrderId}`,
      headers,
      body: JSON.stringify({ status: 'confirmed' })
    });

    // 4. Decrementar bowls disponibles
    const configResponse = await this.helpers.httpRequest({
      method: 'GET',
      url: `${SUPABASE_URL}/rest/v1/config_diaria?fecha=eq.${new Date().toISOString().split('T')[0]}`,
      headers
    });

    const configData = Array.isArray(configResponse) ? configResponse[0] : configResponse;

    if (configData && configData.id) {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: `${SUPABASE_URL}/rest/v1/config_diaria?id=eq.${configData.id}`,
        headers,
        body: JSON.stringify({ bowls_vendidos: configData.bowls_vendidos + 1 })
      });
    }

    return `Pedido guardado y confirmado. ID: ${newOrderId}`;

  } else if (action === 'cancel') {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SUPABASE_URL}/rest/v1/orders?id=eq.${order_id}`,
      headers,
      body: JSON.stringify({ status: 'cancelled' })
    });
    return 'Pedido cancelado exitosamente.';
  }

  return `action no reconocida: ${action}`;

} catch(e) {
  return `ERROR: ${e.message}`;
}

